WITH e AS (SELECT * FROM json_to_recordset($1::json) AS q(stay_id integer,subject_id integer,hadm_id integer,time_zero timestamp)) SELECT e.stay_id,ie.itemid,ie.rate,ie.rateuom,ie.patientweight,ie.starttime,ie.endtime,EXTRACT(EPOCH FROM (e.time_zero-ie.starttime))/3600.0 AS hours_before_t0 FROM e JOIN mimiciv_icu.inputevents ie ON ie.stay_id=e.stay_id AND ie.itemid IN (221906,221289,221662,221653) AND ie.rate>0 AND ie.starttime<=e.time_zero AND ie.endtime>=e.time_zero-INTERVAL '24 hours';
